```json
{
  "root_causes": [
    {
      "service": "ts-route-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, approx_quantile(duration/1e6, 0.5) AS p50_ms, approx_quantile(duration/1e6, 0.95) AS p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Internal' GROUP BY 1 ORDER BY 3 DESC",
          "claim": "Route-plan internal RoutePlanController methods take about 1855 ms p50 in the abnormal period, versus about 37 ms p50 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, c.service_name, count(*) AS n, approx_quantile(c.duration/1e6, 0.95) AS p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-route-plan-service' AND p.span_name LIKE '%cheapestRoute%' GROUP BY 1,2",
          "claim": "The slow getCheapestRoutes internal span has no child spans, so the ~1860 ms is self time inside route-plan."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, p.attr_span_kind, approx_quantile(p.duration/1e6, 0.95) AS p_p95_ms, approx_quantile(c.duration/1e6, 0.95) AS child_p95_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-travel-plan-service' AND p.span_name LIKE '%TravelPlanController.getByCheapest%' GROUP BY 1,2,3",
          "claim": "Travel-plan's getByCheapest and its client span to route-plan both sit near 1865 ms, matching route-plan's slow time."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, approx_quantile(c.duration/1e6, 0.95) AS travel_plan_p95_ms, count(*) AS n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY 1,2",
          "claim": "Ui-dashboard's calls into travel-plan take about 1860 ms p95 in the abnormal period, which is the user-facing slowdown."
        }
      ]
    }
  ]
}
```

